function paginaProducto(int $p,array $q):string {return 'index.php?'.http_build_query($q+['pagina'=>$p]);}
function estadoProducto(array $p):array {
    $activo=in_array($p['activo'],['t','true','1',1,true],true);
    if (!$activo) return ['Inactivo','off'];
    if ((int)$p['stock_disponible']<=0) return ['Agotado','bad'];
    if ((int)$p['stock_disponible']<=(int)$p['stock_minimo']) return ['Poco stock','warn'];
    return ['Disponible','ok'];
}
