<script>
(function(){const v=document.querySelector('#precio'),c=document.querySelector('#costo'),m=document.querySelector('#margen');function calc(){const p=Number(v.value),cost=Number(c.value);m.innerHTML=p>0&&Number.isFinite(cost)?'Margen bruto estimado: <strong>'+((p-cost)/p*100).toFixed(1)+'% ($'+(p-cost).toFixed(2)+' MXN)</strong>':'Margen bruto estimado: <strong>—</strong>';}v.addEventListener('input',calc);c.addEventListener('input',calc);calc();})();
</script>
